import { firebaseConfig } from './firebase-config.js';

const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const uid = () => Math.random().toString(36).slice(2,10);
const today = new Date().toISOString().slice(0,10);
const COVER = './assets/default-cover.jpg';
const DEMO_SONGS = [
  {id:'s1',title:'Gangster',artist:'Cholos in Paris',releaseDate:'2026-11-11',type:'master',published:true,cover:COVER,collaborators:'',lyrics:'Noche larga, luces sobre el boulevard\nTodo lo que fuimos vuelve a comenzar\n\nBajo la luna, sin mirar atrás\nGangster como un sueño que no va a acabar',audioUrl:'',versions:[{name:'Master final',type:'master',date:'2026-11-10'},{name:'Maqueta 03',type:'maqueta',date:'2026-10-25'},{name:'Composición',type:'composición',date:'2026-10-03'}],projectIds:['p1']},
  {id:'s2',title:'París de noche',artist:'Cholos in Paris',releaseDate:'2026-09-22',type:'maqueta',published:false,cover:COVER,collaborators:'Luna Sol',lyrics:'La ciudad despierta cuando tú te vas\nParís de noche, no quiero regresar',audioUrl:'',versions:[{name:'Maqueta 01',type:'maqueta',date:'2026-09-20'}],projectIds:[]},
  {id:'s3',title:'Sin señal',artist:'Cholos in Paris',releaseDate:'2026-07-14',type:'composición',published:true,cover:COVER,collaborators:'',lyrics:'',audioUrl:'',versions:[{name:'Master final',type:'master',date:'2026-07-13'},{name:'Composición',type:'composición',date:'2026-06-29'}],projectIds:['p1']},
  {id:'s4',title:'Ceniza',artist:'Cholos in Paris',releaseDate:'2025-12-05',type:'master',published:true,cover:COVER,collaborators:'Milo',lyrics:'',audioUrl:'',versions:[{name:'Master final',type:'master',date:'2025-12-04'}],projectIds:[]},
  {id:'s5',title:'Otra vida',artist:'Cholos in Paris',releaseDate:'2025-03-02',type:'maqueta',published:false,cover:COVER,collaborators:'',lyrics:'',audioUrl:'',versions:[],projectIds:[]}
];
const DEMO_PROJECTS=[{id:'p1',title:'Ciudad fantasma',artist:'Cholos in Paris',releaseDate:'2026-11-16',cover:COVER,collaborators:'Luna Sol',published:false,trackIds:['s1','s3'],description:'Un recorrido por las noches que se quedan con nosotros.'}];
let state = {view:'catalog',catalogMode:'list',catalogSearch:'',catalogFilter:'all',catalogSort:'date',projectSearch:'',platform:'Spotify',simPage:'profile',simFilter:'all',selectedSong:null,selectedProject:null,playerSong:null,playing:false,seconds:0,modal:null,authMode:'signup',profile:{name:'',bio:'',avatar:'',banner:''},settings:{dark:true},songs:[],projects:[],user:null,firebase:null,db:null,storage:null,auth:null};
let timer=null;
const saved=()=>{try{return JSON.parse(localStorage.getItem('chip-studio-state')||'{}')}catch{return {}}};
function persistLocal(){const clean=(items)=>items.map(({sessionAudio,...record})=>({...record,versions:(record.versions||[]).map(({sessionAudio,...v})=>v)}));const data={songs:clean(state.songs),projects:state.projects,profile:state.profile,settings:state.settings};localStorage.setItem(state.user?`chip-studio-state-${state.user.uid}`:'chip-studio-state',JSON.stringify(data));$('#save-state').textContent=state.db?'Sincronizado':'Guardado localmente';}
function toast(message){const t=document.createElement('div');t.className='toast';t.textContent=message;$('#toast-root').append(t);setTimeout(()=>t.remove(),2600)}
function dateLabel(date){if(!date)return'—';return new Intl.DateTimeFormat('es-MX',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${date}T12:00:00`))}
function durationSec(value){const [m,s]=String(value||'3:00').split(':').map(Number);return (m||0)*60+(s||0)}
function fmtTime(sec){return `${Math.floor(sec/60)}:${String(Math.floor(sec%60)).padStart(2,'0')}`}
function escapeHtml(value=''){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function songTag(song){return song.published?'publicada':(song.type||'maqueta')}
function songById(id){return state.songs.find(s=>s.id===id)}
function sortedSongs(list=state.songs){return [...list].sort((a,b)=>(b.releaseDate||'').localeCompare(a.releaseDate||''))}
function imageOr(url,fallback=COVER){return url||fallback}
function identity(){const n=state.profile.name||'Artista';$('#side-name').textContent=n;$('#top-avatar').textContent=n.slice(0,1).toUpperCase();$('#side-avatar').textContent=n.slice(0,1).toUpperCase();$('#crumb-current').textContent=({catalog:'Catálogo',projects:'Proyectos',spotify:state.platform,apps:'Otras apps',profile:'Perfil'})[state.view]||'Catálogo';const photo=state.profile.avatar||'';for(const el of [$('#top-avatar'),$('#side-avatar')]){el.style.backgroundImage=photo?`url("${photo}")`:'';el.style.backgroundSize='cover';el.textContent=photo?'':n.slice(0,1).toUpperCase()}}
function navActive(){$$('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view))}
function setView(view){state.view=view;if(view!=='spotify')document.body.dataset.preview='studio';identity();navActive();render();$('.sidebar').classList.remove('open');window.scrollTo(0,0)}
function render(){const root=$('#view-root');root.innerHTML=state.view==='catalog'?renderCatalog():state.view==='projects'?renderProjects():state.view==='spotify'?renderPlatform(state.platform):state.view==='apps'?renderApps():renderProfile();const hero=$('.sim-hero');if(hero&&state.profile.banner)hero.style.backgroundImage=`linear-gradient(0deg,#121613 0%,#121613a8 43%,#12161333 100%),url("${state.profile.banner}")`;const bio=$('.sim-hero p');if(bio&&state.simPage==='profile'&&state.profile.bio)bio.textContent=`${state.profile.bio} · ${bio.textContent}`;if(state.view==='spotify'&&state.simPage==='discography'){const filterCards=()=>$$('.catalog-card',root).forEach(card=>{if(state.simFilter==='all')card.hidden=false;else card.hidden=Boolean(card.dataset.play)!==(state.simFilter==='songs')});filterCards();$$('[data-sim-filter]',root).forEach(button=>button.onclick=()=>{state.simFilter=button.dataset.simFilter;render()})}bindViewEvents()}
function bindExpandedPlayer(){if(state.simPage!=='player')return;const seek=$('#expanded-seek'),audio=window.currentAudio;if(!seek)return;const elapsed=$('#expanded-elapsed'),total=$('#expanded-total');const paint=()=>{if(!audio)return;if(Number.isFinite(audio.duration)){seek.value=100*audio.currentTime/audio.duration;total.textContent=fmtTime(audio.duration)}elapsed.textContent=fmtTime(audio.currentTime)};if(audio){audio.addEventListener('timeupdate',paint);paint();seek.oninput=()=>{if(Number.isFinite(audio.duration))audio.currentTime=audio.duration*(+seek.value/100)};$('#player-volume')?.addEventListener('input',e=>audio.volume=+e.target.value)}$('[data-player-prev]').forEach(b=>b.onclick=()=>stepPublished(-1));$('[data-player-next]').forEach(b=>b.onclick=()=>stepPublished(1))}function stepPublished(delta){const items=sortedSongs(state.songs.filter(song=>song.published)),index=items.findIndex(song=>song.id===state.playerSong?.id),next=items[(index+delta+items.length)%items.length];if(next)playSong(next)}
function renderCatalog(){let list=sortedSongs();const q=state.catalogSearch.toLowerCase().trim();if(q)list=list.filter(s=>[s.title,s.artist,s.collaborators,s.type].join(' ').toLowerCase().includes(q));if(state.catalogFilter==='published')list=list.filter(s=>s.published);if(state.catalogFilter==='draft')list=list.filter(s=>!s.published);if(state.catalogFilter==='maqueta'||state.catalogFilter==='master'||state.catalogFilter==='composición')list=list.filter(s=>s.type===state.catalogFilter);if(state.catalogSort==='title')list.sort((a,b)=>a.title.localeCompare(b.title));return `<div class="page-head"><div><div class="eyebrow">TU MÚSICA · ${state.songs.length} CANCIONES</div><h1>Catálogo</h1><p>Todo lo que estás creando, en un mismo lugar.</p></div><div class="button-row"><button class="button" data-action="new-project">＋ Proyecto</button><button class="button primary" data-action="new-song">＋ Nueva canción</button></div></div><div class="tabs"><button class="tab ${state.catalogMode==='list'?'active':''}" data-mode="list">Canciones</button><button class="tab ${state.catalogMode==='covers'?'active':''}" data-mode="covers">Portadas</button></div><div class="toolbar"><label class="searchbox"><span>⌕</span><input id="catalog-search" value="${escapeHtml(state.catalogSearch)}" placeholder="Buscar canciones, colaboradores…" /></label><select class="select-filter" id="catalog-filter"><option value="all">Todos los estados</option><option value="published">Publicadas</option><option value="draft">Borradores</option><option value="maqueta">Maqueta</option><option value="composición">Composición</option><option value="master">Master</option></select><select class="select-filter" id="catalog-sort"><option value="date">Más recientes</option><option value="title">Nombre A–Z</option></select></div>${!list.length?`<div class="empty-state"><div style="font-size:24px">♫</div><h3>${q?'No encontramos canciones':'Tu catálogo empieza aquí'}</h3><p>${q?'Prueba con otro nombre o filtro.':'Crea una canción para empezar a construir tu espacio musical.'}</p>${!q?'<button class="button primary" data-action="new-song">Crear canción</button>':''}</div>`:state.catalogMode==='list'?`<div class="music-table"><div class="table-head"><span>CANCIÓN</span><span>ESTADO</span><span>FECHA</span><span>PROYECTO</span><span></span></div>${list.map(songRow).join('')}</div>`:`<div class="catalog-grid">${list.map(s=>`<article class="catalog-card" data-song="${s.id}"><img src="${imageOr(s.cover)}" alt="Portada de ${escapeHtml(s.title)}"><div class="card-bottom"><span class="tag ${songTag(s)}">${songTag(s).toUpperCase()}</span><span class="table-muted">${dateLabel(s.releaseDate)}</span></div><h3>${escapeHtml(s.title)}</h3><p>${escapeHtml(s.collaborators?`${state.profile.name} · ${s.collaborators}`:state.profile.name)}</p></article>`).join('')}</div>`}`}
function songRow(s){const project=s.projectIds?.map(id=>state.projects.find(p=>p.id===id)?.title).filter(Boolean)[0]||'Sencillo';return `<div class="song-row" data-song="${s.id}"><div class="track-cell"><div class="track-meta"><strong>${escapeHtml(s.title)}</strong><small>${escapeHtml(s.collaborators?`${state.profile.name} · feat. ${s.collaborators}`:state.profile.name)}</small></div></div><span><i class="tag ${songTag(s)}">${songTag(s).toUpperCase()}</i></span><span class="table-muted">${dateLabel(s.releaseDate)}</span><span class="table-muted">${escapeHtml(project)}</span><span class="row-actions"><button class="small-icon" data-play="${s.id}" title="Reproducir">▶</button><button class="small-icon" data-edit-song="${s.id}" title="Editar">···</button></span></div>`}
function renderProjects(){const q=state.projectSearch.toLowerCase();const list=state.projects.filter(p=>p.title.toLowerCase().includes(q));return `<div class="page-head"><div><div class="eyebrow">DISCOGRAFÍA · ${state.projects.length} PROYECTOS</div><h1>Proyectos</h1><p>Arma EPs y álbumes a partir de canciones de tu catálogo.</p></div><button class="button primary" data-action="new-project">＋ Nuevo proyecto</button></div><div class="toolbar"><label class="searchbox"><span>⌕</span><input id="project-search" value="${escapeHtml(state.projectSearch)}" placeholder="Buscar proyectos…" /></label><span class="table-muted">Ordenados por fecha de lanzamiento</span></div>${!list.length?'<div class="empty-state"><h3>Aún no hay proyectos</h3><p>Reúne tus canciones en un EP o álbum.</p><button class="button primary" data-action="new-project">Crear proyecto</button></div>':`<div class="projects-grid">${[...list].sort((a,b)=>(b.releaseDate||'').localeCompare(a.releaseDate||'')).map(p=>`<article class="project-card" data-edit-project="${p.id}"><img src="${imageOr(p.cover)}" alt=""><div class="card-bottom"><span class="tag ${p.published?'publicada':'maqueta'}">${p.published?'PUBLICADO':'BORRADOR'}</span><span class="table-muted">${p.trackIds?.length||0} tracks</span></div><h3>${escapeHtml(p.title)}</h3><p>${dateLabel(p.releaseDate)} · ${escapeHtml(p.collaborators||state.profile.name)}</p></article>`).join('')}</div>`}`}
function renderApps(){return `<div class="page-head"><div><div class="eyebrow">DISTRIBUCIÓN · SIMULADORES</div><h1>Otras apps</h1><p>Revisa cómo se ve lo que publicas en cada plataforma.</p></div></div><div class="projects-grid">${[['YouTube','▶','Una página de artista inspirada en YouTube.'],['SoundCloud','☁','Perfil, tracks y proyectos con estética de audio social.'],['Apple Music','♫','Vista de artista con discografía y reproductor extendido.']].map(([name,icon,description])=>`<article class="project-card app-card" data-platform="${name}"><div style="aspect-ratio:1.25;border-radius:8px;background:linear-gradient(135deg,#34382e,#171916);display:grid;place-items:center;font-size:45px;color:var(--lime)">${icon}</div><div class="card-bottom"><span class="sim-platform">SIMULADOR</span><span class="table-muted">↗</span></div><h3>${name}</h3><p>${description}</p><button class="button" style="margin-top:14px;width:100%">Abrir simulación</button></article>`).join('')}</div><div class="panel" style="margin-top:22px"><h3>Una sola publicación</h3><p class="table-muted" style="line-height:1.7;margin:0">Al publicar una canción o proyecto, aparece automáticamente en todas estas vistas. Una canción también puede formar parte de un álbum y conservar su publicación como sencillo, con portada y fecha propias.</p></div>`}
function renderProfile(){return `<div class="page-head"><div><div class="eyebrow">IDENTIDAD · CUENTA</div><h1>Tu perfil</h1><p>Administra la identidad que aparece en todas las simulaciones.</p></div><button class="button" data-action="account">Cuenta y acceso</button></div><div class="profile-hero"><img class="profile-banner" id="profile-banner-preview" src="${state.profile.banner||''}" alt="" ${state.profile.banner?'':'hidden'}><div class="profile-identity"><img class="avatar" src="${imageOr(state.profile.avatar,COVER)}"><div><h2>${escapeHtml(state.profile.name)}</h2><p>Perfil público del artista</p></div></div></div><div class="profile-layout"><div class="panel"><h3>Identidad del artista</h3><div class="form-grid"><div class="field full"><label>Nombre de artista</label><input id="profile-name" value="${escapeHtml(state.profile.name)}" placeholder="Tu nombre artístico"></div><div class="field full"><label>Descripción</label><textarea id="profile-bio" placeholder="Cuéntale al mundo sobre tu música">${escapeHtml(state.profile.bio||'')}</textarea></div><div class="field"><label>Foto de perfil</label><label class="file-picker">＋ Elegir imagen<input type="file" id="profile-avatar" accept="image/*"></label><img class="profile-upload-preview" id="profile-avatar-preview" src="${state.profile.avatar||COVER}" alt="Vista previa de foto"></div><div class="field"><label>Banner</label><label class="file-picker">＋ Elegir banner<input type="file" id="profile-banner" accept="image/*"></label></div></div><div class="button-row" style="margin-top:16px"><button class="button primary" data-action="save-profile">Guardar perfil</button></div></div><div class="panel"><h3>Preferencias y cuenta</h3><div class="setting-row"><div><strong>Modo oscuro</strong><small>Ajusta la apariencia del estudio</small></div><input class="switch" id="dark-switch" type="checkbox" ${state.settings.dark?'checked':''}></div><div class="setting-row"><div><strong>Almacenamiento</strong><small>${state.db?'Firebase conectado':'Modo de demostración local'}</small></div><span class="tag ${state.db?'publicada':'master'}">${state.db?'EN LÍNEA':'DEMO'}</span></div><div class="setting-row"><div><strong>Sesión</strong><small>${state.user?.email||'No has iniciado sesión'}</small></div><button class="button" data-action="account">${state.user?'Salir':'Iniciar sesión'}</button></div><div class="setting-row"><div><strong>Datos de ejemplo</strong><small>Reinicia el catálogo de demostración</small></div><button class="button danger" data-action="reset-demo">Reiniciar</button></div></div></div>`}

function enhanceDropdowns(root=document){root.querySelectorAll('select:not([data-smart-select])').forEach(select=>{select.dataset.smartSelect='true';const wrap=document.createElement('div');wrap.className='smart-select';const trigger=document.createElement('button');trigger.type='button';trigger.className='smart-select-trigger';trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');const menu=document.createElement('div');menu.className='smart-select-menu';menu.setAttribute('role','listbox');const close=()=>{wrap.classList.remove('open');trigger.setAttribute('aria-expanded','false')};const paint=()=>{trigger.innerHTML='<span>'+escapeHtml(select.selectedOptions[0]?.textContent||'Elige una opción')+'</span><b aria-hidden="true">⌄</b>';menu.innerHTML=[...select.options].map((option,index)=>'<button type="button" role="option" aria-selected="'+(option.selected?'true':'false')+'" '+(option.disabled?'disabled':'')+' data-option-index="'+index+'">'+escapeHtml(option.textContent)+'</button>').join('')};paint();trigger.onclick=()=>{const open=wrap.classList.toggle('open');trigger.setAttribute('aria-expanded',String(open))};menu.addEventListener('click',event=>{const option=event.target.closest('[data-option-index]');if(!option)return;select.selectedIndex=+option.dataset.optionIndex;select.dispatchEvent(new Event('change',{bubbles:true}));close()});select.after(wrap);wrap.append(trigger,menu);select.classList.add('smart-select-native');select.addEventListener('change',paint);document.addEventListener('click',event=>{if(!wrap.contains(event.target))close()});trigger.addEventListener('keydown',event=>{if(event.key==='Escape')close();if(event.key==='ArrowDown'){event.preventDefault();wrap.classList.add('open');trigger.setAttribute('aria-expanded','true');menu.querySelector('button:not([disabled])')?.focus()}});menu.addEventListener('keydown',event=>{if(event.key==='Escape'){close();trigger.focus()}if(event.key==='ArrowDown'){event.preventDefault();event.target.nextElementSibling?.focus()}if(event.key==='ArrowUp'){event.preventDefault();event.target.previousElementSibling?.focus()}})})}
function showModal(title,body,footer=''){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal"><header class="modal-header"><h2>${title}</h2><button class="close-modal" data-close>×</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;$('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});$('[data-close]').onclick=closeModal;state.modal=title;enhanceVersionEditor(title);enhanceDropdowns(root)}
function enhanceVersionEditor(title){if(!title.toLowerCase().includes('canción')||!state.activeSongEditor)return;const song=state.activeSongEditor.song;$$('.version-row').forEach((row,index)=>{const version=song.versions[index],name=$('strong',row);if(!version||!name)return;const input=document.createElement('input');input.className='version-name';input.value=version.name||'';input.setAttribute('aria-label',`Nombre de versión ${index+1}`);input.oninput=()=>version.name=input.value;name.replaceWith(input);const remove=document.createElement('button');remove.className='version-delete';remove.type='button';remove.textContent='Eliminar';remove.setAttribute('aria-label',`Eliminar versión ${version.name||index+1}`);remove.onclick=()=>{song.versions.splice(index,1);state.activeSongEditor.redraw()};row.append(remove)})}
function closeModal(){if(state.cropResolver){const cancel=state.cropResolver;state.cropResolver=null;cancel();return}$('#modal-root').innerHTML='';state.modal=null}
function songEditor(id,options={}){const existing=id?songById(id):null;const s=existing?structuredClone(existing):{id:uid(),title:'',artist:state.profile.name,releaseDate:today,type:'maqueta',published:false,cover:'',collaborators:'',lyrics:'',audioUrl:'',versions:[]};state.selectedSong=s.id;state.activeSongEditor={song:s};let tab='general';const draw=()=>{if(state.activeSongEditor)state.activeSongEditor.redraw=draw;const body=tab==='general'?`<div class="edit-layout"><div class="upload-cover"><img class="edit-cover" src="${imageOr(s.cover)}" id="song-cover-preview"><label class="file-picker">＋ Portada<input type="file" accept="image/*" id="song-cover-file"></label><label class="file-picker">♫ Audio<input type="file" accept="audio/*" id="song-audio-file"></label><small id="upload-status" class="upload-status"></small>${s.audioUrl||s.sessionAudio?'<span class="tag master">AUDIO CARGADO</span>':''}</div><div class="editor-fields"><div class="form-grid"><div class="field full"><label>Nombre de la canción *</label><input id="song-title" value="${escapeHtml(s.title)}" placeholder="Nombre de la canción"></div><div class="field"><label>Fecha de lanzamiento *</label><input id="song-date" type="date" value="${s.releaseDate||today}"></div><div class="field"><label>Tipo de versión</label><select id="song-type"><option ${s.type==='maqueta'?'selected':''}>maqueta</option><option ${s.type==='composición'?'selected':''}>composición</option><option ${s.type==='master'?'selected':''}>master</option></select></div><div class="field full"><label>Artistas colaboradores</label><div class="collab-entry" id="song-collab-entry"></div><input type="hidden" id="song-collabs" value="${escapeHtml(s.collaborators||'')}"><small class="table-muted">Escribe un nombre y pulsa Enter para añadir cada artista.</small></div></div><p class="table-muted" style="line-height:1.6;margin-top:14px">Nombre y fecha son los únicos datos obligatorios. Si no agregas duración, usamos 3:00; sin colaboradores, solo se muestra tu nombre artístico.</p></div></div>`:tab==='lyrics'?`<div class="field"><label>Letra de la canción</label><textarea class="lyrics-box" id="song-lyrics" placeholder="Empieza a escribir…">${escapeHtml(s.lyrics||'')}</textarea></div><div class="panel" style="margin-top:15px;display:flex;align-items:center;gap:12px"><button class="play-main" data-audio-play>▶</button><div><strong style="font-size:11px">${escapeHtml(s.title||'Pista actual')}</strong><small class="table-muted" style="display:block;margin-top:3px">${s.audioUrl||s.sessionAudio?'Pista disponible':'Sube un audio desde la pestaña General'}</small></div><span class="table-muted" style="margin-left:auto">${s.duration||'3:00'}</span></div>`:`<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px"><div><h3 style="margin:0 0 5px;font-size:13px">Historial de versiones</h3><p class="table-muted" style="margin:0">Una línea de tiempo sencilla, de la primera idea al master.</p></div><button class="button" data-add-version>＋ Nueva versión</button></div><div class="version-list">${(s.versions||[]).map((v,i)=>`<div class="version-row"><span class="version-number">${String((s.versions.length-i)).padStart(2,'0')}</span><div><strong>${escapeHtml(v.name)}</strong><small>${escapeHtml(v.type)} · ${dateLabel(v.date)} ${v.audioUrl?'· audio cargado':''}</small></div><label class="button" style="font-size:10px">Subir audio<input type="file" accept="audio/*" data-version-file="${i}" hidden></label><button class="small-icon" data-version-play="${i}" title="Reproducir">▶</button></div>`).join('')||'<div class="empty-state"><p>Aún no hay versiones guardadas.</p></div>'}</div>`;const footer=`<span class="table-muted">${s.published?'Visible en las simulaciones':'Borrador privado'}</span><div class="button-row">${existing?'<button class="button danger" data-song-delete>Eliminar</button>':''}<button class="button" data-song-save>Guardar</button><button class="button ${s.published?'danger':'primary'}" data-song-publish>${s.published?'Despublicar':'Publicar'}</button></div>`;showModal(id?'Editar canción':'Nueva canción',`<div class="tabs">${['general','lyrics','versions'].map((t,i)=>`<button class="tab ${tab===t?'active':''}" data-editor-tab="${t}">${['General','Letra','Versiones'][i]}</button>`).join('')}</div>${body}`,footer);bindCollaboratorChips('song-collab-entry','song-collab-input','song-collabs');$$('[data-editor-tab]').forEach(b=>b.onclick=()=>{syncSongFields(s,tab);tab=b.dataset.editorTab;draw()});$('#song-cover-file')?.addEventListener('change',e=>uploadFile(e.target.files[0],'cover',s,draw));$('#song-audio-file')?.addEventListener('change',e=>uploadFile(e.target.files[0],'audio',s,draw));$$('[data-version-file]').forEach(input=>input.addEventListener('change',e=>uploadFile(e.target.files[0],'audio',s.versions[+input.dataset.versionFile],draw)));$$('[data-version-play]').forEach(b=>b.onclick=()=>{const v=s.versions[+b.dataset.versionPlay];if(v.sessionAudio||v.audioUrl)playSong({...s,title:`${s.title} · ${v.name}`,sessionAudio:v.sessionAudio,audioUrl:v.audioUrl});else toast('Sube un archivo de audio para esta versión')});$('[data-song-delete]')?.addEventListener('click',()=>{if(!existing)return;showModal('Eliminar canción',`<div class="delete-confirm"><span>♪</span><div><strong>¿Eliminar “${escapeHtml(s.title)}”?</strong><p>Se quitará del catálogo y de los tracklists donde aparezca. Esta acción no se puede deshacer.</p></div></div>`,`<button class="button" data-close>Conservar canción</button><button class="button danger" data-delete-song-confirm>Eliminar canción</button>`);$('[data-delete-song-confirm]').onclick=async()=>{state.songs=state.songs.filter(item=>item.id!==s.id);state.projects.forEach(project=>{project.trackIds=(project.trackIds||[]).filter(id=>id!==s.id);cloudSave('projects',project)});persistLocal();if(state.db&&state.user){try{const {doc,deleteDoc}=await import('https://www.gstatic.com/firebasejs/11.0.2/firebase-firestore.js');await deleteDoc(doc(state.db,'users',state.user.uid,'songs',s.id))}catch(error){console.error(error);toast('No se pudo sincronizar la eliminación');return}}closeModal();render();toast('Canción eliminada')}});$('[data-song-save]').onclick=()=>{syncSongFields(s,tab);if(!s.title.trim()||!s.releaseDate){toast('Completa nombre y fecha de lanzamiento');return}saveSong(s);if(options.onSave){closeModal();options.onSave(s);toast('Canción guardada y añadida al proyecto');return}closeModal();render();toast('Canción guardada')};$('[data-song-publish]').onclick=()=>{syncSongFields(s,tab);if(!s.title.trim()||!s.releaseDate){toast('Para publicar, completa nombre y fecha');return}s.published=!s.published;saveSong(s);closeModal();render();toast(s.published?'Canción publicada en tus simulaciones':'Canción despublicada')};$('[data-add-version]')?.addEventListener('click',()=>{syncSongFields(s,tab);s.versions=s.versions||[];s.versions.unshift({name:`Versión ${String(s.versions.length+1).padStart(2,'0')}`,type:s.type||'maqueta',date:today});draw()});$('[data-audio-play]')?.addEventListener('click',()=>{syncSongFields(s,tab);if(s.sessionAudio||s.audioUrl)playSong(s);else toast('Sube una pista de audio en General')})};draw()}
function syncSongFields(s,tab){if($('#song-title'))s.title=$('#song-title').value;if($('#song-date'))s.releaseDate=$('#song-date').value;if($('#song-type'))s.type=$('#song-type').value;if($('#song-collabs')){const pending=$('#song-collab-input')?.value.trim();s.collaborators=[...new Set([$('#song-collabs').value,...(pending?[pending]:[])].flatMap(x=>x.split(',')).map(x=>x.trim()).filter(Boolean))].join(', ')}if($('#song-lyrics'))s.lyrics=$('#song-lyrics').value}
function saveSong(s){s.artist=state.profile.name;delete s.duration;const idx=state.songs.findIndex(x=>x.id===s.id);if(idx<0)state.songs.push(s);else state.songs[idx]=s;persistLocal();cloudSave('songs',s)}
function projectEditor(id){const old=id?state.projects.find(p=>p.id===id):null;const p=old?structuredClone(old):{id:uid(),title:'',artist:state.profile.name,releaseDate:today,cover:'',collaborators:'',published:false,trackIds:[],description:''};let tab='general',search='';const draw=()=>{const body=tab==='general'?`<div class="edit-layout"><div class="upload-cover"><img class="edit-cover" id="project-cover-preview" src="${imageOr(p.cover)}"><label class="file-picker">＋ Portada del proyecto<input type="file" id="project-cover-file" accept="image/*"></label><small id="upload-status" class="upload-status"></small></div><div class="form-grid"><div class="field full"><label>Nombre del proyecto *</label><input id="project-title" value="${escapeHtml(p.title)}" placeholder="Nombre del álbum o EP"></div><div class="field"><label>Fecha de lanzamiento *</label><input id="project-date" type="date" value="${p.releaseDate||today}"></div><div class="field"><label>Artistas colaboradores</label><input id="project-collabs" value="${escapeHtml(p.collaborators||'')}" placeholder="Nombres, no perfiles"></div><div class="field full"><label>Descripción</label><textarea id="project-desc" placeholder="Una nota sobre este proyecto">${escapeHtml(p.description||'')}</textarea></div></div></div>`:`<div class="toolbar"><label class="searchbox"><span>⌕</span><input id="track-search" value="${escapeHtml(search)}" placeholder="Buscar en tu catálogo…"></label><button class="button" data-create-track>＋ Crear canción</button></div><div class="track-list" id="project-track-list">${(p.trackIds||[]).map((sid,i)=>{const s=songById(sid);return s?`<div class="track-list-item" draggable="true" data-track-index="${i}"><span class="table-muted">${String(i+1).padStart(2,'0')}</span><img src="${imageOr(s.cover)}"><span>${escapeHtml(s.title)}</span><button data-move-up="${i}">↑</button><button data-move-down="${i}">↓</button><button data-remove-track="${sid}">×</button></div>`:''}).join('')||'<div class="empty-state"><p>Añade canciones desde tu catálogo para armar el orden del proyecto.</p></div>'}</div><div class="search-results" id="track-results"></div>`;showModal(id?'Editar proyecto':'Nuevo proyecto',`<div class="tabs"><button class="tab ${tab==='general'?'active':''}" data-project-tab="general">General</button><button class="tab ${tab==='tracks'?'active':''}" data-project-tab="tracks">Tracks · ${p.trackIds.length}</button></div>${body}`,`<span class="table-muted">${p.published?'Visible en las simulaciones':'Borrador privado'}</span><div class="button-row"><button class="button" data-project-save>Guardar</button><button class="button ${p.published?'danger':'primary'}" data-project-publish>${p.published?'Despublicar':'Publicar'}</button></div>`);$$('[data-project-tab]').forEach(b=>b.onclick=()=>{syncProject(p);tab=b.dataset.projectTab;draw()});$('#project-cover-file')?.addEventListener('change',e=>uploadFile(e.target.files[0],'cover',p,draw));$('[data-project-save]').onclick=()=>{syncProject(p);if(!p.title.trim()||!p.releaseDate){toast('Completa nombre y fecha de lanzamiento');return}saveProject(p);closeModal();render();toast('Proyecto guardado')};$('[data-project-publish]').onclick=()=>{syncProject(p);if(!p.title.trim()||!p.releaseDate){toast('Para publicar, completa nombre y fecha');return}p.published=!p.published;saveProject(p);closeModal();render();toast(p.published?'Proyecto publicado':'Proyecto despublicado')};$('#track-search')?.addEventListener('input',e=>{search=e.target.value;drawResults()});$('[data-create-track]')?.addEventListener('click',()=>songEditor(null,{onSave:(song)=>{if(!p.trackIds.includes(song.id))p.trackIds.push(song.id);syncProject(p);saveProject(p);tab='tracks';draw()}}));$$('[data-remove-track]').forEach(b=>b.onclick=()=>{p.trackIds=p.trackIds.filter(x=>x!==b.dataset.removeTrack);draw()});$$('[data-move-up]').forEach(b=>b.onclick=()=>moveTrack(p,+b.dataset.moveUp,-1,draw));$$('[data-move-down]').forEach(b=>b.onclick=()=>moveTrack(p,+b.dataset.moveDown,1,draw));let dragFrom=null;$$('.track-list-item').forEach(row=>{row.ondragstart=()=>dragFrom=+row.dataset.trackIndex;row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();const to=+row.dataset.trackIndex;const [item]=p.trackIds.splice(dragFrom,1);p.trackIds.splice(to,0,item);draw()}});function drawResults(){const res=$('#track-results');if(!res)return;const query=search.trim().toLowerCase();const matches=sortedSongs(state.songs.filter(s=>!p.trackIds.includes(s.id)&&[s.title,s.collaborators,s.type].join(' ').toLowerCase().includes(query)));res.innerHTML=matches.length?matches.map(s=>`<button class="search-result" data-add-track="${s.id}"><img src="${imageOr(s.cover)}"><span>${escapeHtml(s.title)}<small class="table-muted" style="display:block">${dateLabel(s.releaseDate)}</small></span><b style="color:var(--lime)">＋</b></button>`).join(''):'<p class="table-muted" style="padding:10px;margin:0">Busca canciones para añadirlas al tracklist.</p>';$$('[data-add-track]',res).forEach(b=>b.onclick=()=>{p.trackIds.push(b.dataset.addTrack);search='';draw()})}drawResults()};draw()}
function moveTrack(p,index,delta,draw){const n=index+delta;if(n<0||n>=p.trackIds.length)return;[p.trackIds[index],p.trackIds[n]]=[p.trackIds[n],p.trackIds[index]];draw()}
function syncProject(p){if($('#project-title'))p.title=$('#project-title').value;if($('#project-date'))p.releaseDate=$('#project-date').value;if($('#project-collabs'))p.collaborators=$('#project-collabs').value.trim();if($('#project-desc'))p.description=$('#project-desc').value}
function saveProject(p){p.artist=state.profile.name;const i=state.projects.findIndex(x=>x.id===p.id);if(i<0)state.projects.push(p);else state.projects[i]=p;persistLocal();cloudSave('projects',p)}
function bindCollaboratorChips(entryId,inputId,hiddenId){const entry=$('#'+entryId),hidden=$('#'+hiddenId);if(!entry||!hidden)return;let names=hidden.value.split(',').map(x=>x.trim()).filter(Boolean);const paint=(focus=false)=>{hidden.value=names.join(', ');entry.innerHTML=names.map((name,i)=>`<span class="collab-chip">${escapeHtml(name)}<button type="button" data-chip-remove="${i}" aria-label="Quitar ${escapeHtml(name)}">×</button></span>`).join('')+`<input id="${inputId}" autocomplete="off" placeholder="Añadir artista…">`;const input=$('#'+inputId);input.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===','){event.preventDefault();const next=input.value.split(',').map(x=>x.trim()).filter(Boolean);next.forEach(name=>{if(!names.some(existing=>existing.toLowerCase()===name.toLowerCase()))names.push(name)});paint(true)}});input.addEventListener('blur',()=>{const next=input.value.split(',').map(x=>x.trim()).filter(Boolean);next.forEach(name=>{if(!names.some(existing=>existing.toLowerCase()===name.toLowerCase()))names.push(name)});hidden.value=names.join(', ')});entry.querySelectorAll('[data-chip-remove]').forEach(button=>button.onclick=()=>{names.splice(+button.dataset.chipRemove,1);paint()});if(focus)input.focus()};paint()}
function cropImageFile(file,aspect=1){return new Promise(resolve=>{const url=URL.createObjectURL(file),image=new Image(),root=$('#modal-root'),overlay=document.createElement('div'),previousModal=state.modal;let settled=false;const finish=value=>{if(settled)return;settled=true;if(state.cropResolver===cancelCrop)state.cropResolver=null;overlay.remove();URL.revokeObjectURL(url);if(!root.children.length)state.modal=previousModal;resolve(value)};const cancelCrop=()=>finish(null);state.cropResolver=cancelCrop;overlay.className='modal-backdrop crop-overlay';overlay.innerHTML='<section class="modal crop-modal" role="dialog" aria-modal="true" aria-label="Ajusta la imagen"><header class="modal-header"><h2>Ajusta la imagen</h2><button type="button" class="close-modal" data-crop-cancel aria-label="Cerrar">×</button></header><div class="modal-body"><div class="cropper"><p class="table-muted">Arrastra la imagen para centrarla y ajusta el zoom.</p><div class="crop-stage" style="aspect-ratio:'+aspect+'"><img id="crop-image" src="'+url+'" alt="Vista previa para recorte"></div><label class="crop-control">Zoom<input id="crop-zoom" type="range" min="1" max="2.5" step="0.01" value="1"></label></div></div><footer class="modal-footer"><button type="button" class="button" data-crop-cancel>Cancelar</button><button type="button" class="button primary" data-crop-apply>Usar imagen</button></footer></section>';root.append(overlay);let zoom=1,x=.5,y=.5,drag=null;const imageEl=$('#crop-image',overlay),stage=$('.crop-stage',overlay),zoomInput=$('#crop-zoom',overlay),update=()=>{imageEl.style.objectPosition=(x*100)+'% '+(y*100)+'%';imageEl.style.transform='scale('+zoom+')'};zoomInput.oninput=()=>{zoom=+zoomInput.value;update()};stage.onpointerdown=event=>{drag={x:event.clientX,y:event.clientY,ox:x,oy:y};stage.setPointerCapture(event.pointerId)};stage.onpointermove=event=>{if(!drag)return;x=Math.max(0,Math.min(1,drag.ox-(event.clientX-drag.x)/stage.clientWidth));y=Math.max(0,Math.min(1,drag.oy-(event.clientY-drag.y)/stage.clientHeight));update()};stage.onpointerup=()=>drag=null;imageEl.onload=update;overlay.addEventListener('click',event=>{if(event.target===overlay)cancelCrop()});$$('[data-crop-cancel]',overlay).forEach(button=>button.onclick=cancelCrop);$('[data-crop-apply]',overlay).onclick=()=>{const sourceW=image.naturalWidth,sourceH=image.naturalHeight;let cropW,cropH;if(sourceW/sourceH>aspect){cropH=sourceH/zoom;cropW=cropH*aspect}else{cropW=sourceW/zoom;cropH=cropW/aspect}const sx=(sourceW-cropW)*x,sy=(sourceH-cropH)*y,canvas=document.createElement('canvas');canvas.width=aspect>=1?1200:Math.round(1200*aspect);canvas.height=aspect>=1?Math.round(1200/aspect):1200;const context=canvas.getContext('2d');if(!context){finish(null);return}context.drawImage(image,sx,sy,cropW,cropH,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>{if(!blob){finish(null);return}finish(new File([blob],file.name.replace(/\.[^.]+$/,'')+'-cropped.jpg',{type:'image/jpeg'}))},'image/jpeg',.9)};image.onerror=()=>finish(null);image.src=url})}
async function uploadFile(file,kind,record,redraw){if(!file)return;const isAudio=kind==='audio';if(isAudio&&!file.type.startsWith('audio/')){toast('Elige un archivo de audio');return}if(!isAudio&&!file.type.startsWith('image/')){toast('Elige una imagen');return}if(!isAudio){file=await cropImageFile(file,1);if(!file){redraw();return}}toast(isAudio?'Subiendo audio…':'Guardando imagen…');if(state.storage&&state.user){try{const {ref,uploadBytesResumable,getDownloadURL}=await import('https://www.gstatic.com/firebasejs/11.0.2/firebase-storage.js');const path=`users/${state.user.uid}/${isAudio?'audio':'images'}/${record.id||uid()}-${Date.now()}-${file.name.replace(/[^\w.-]/g,'_')}`;const task=uploadBytesResumable(ref(state.storage,path),file,{contentType:file.type});await new Promise((resolve,reject)=>task.on('state_changed',snapshot=>{const percent=Math.round(snapshot.bytesTransferred/snapshot.totalBytes*100);const status=$(statusSelector);if(status)status.textContent=`Subiendo… ${percent}%`},reject,resolve));const url=await getDownloadURL(task.snapshot.ref);if(isAudio)record.audioUrl=url;else record.cover=url}catch(error){console.error(error);toast(error.code==='storage/unauthorized'?'Firebase Storage rechazó el archivo; revisa las reglas.':'No se pudo subir el archivo; inténtalo otra vez.');return}}else if(!isAudio){record.cover=await blobToData(file)}if(isAudio){record.sessionAudio=URL.createObjectURL(file);record.audioFileName=file.name;toast('Audio cargado')}else toast('Imagen guardada');if(state.activeSongEditor?.song&&state.activeSongEditor.song.id===record.id&&state.songs.some(song=>song.id===record.id))saveSong(state.activeSongEditor.song);if(state.projects.some(project=>project.id===record.id))saveProject(record);redraw()}
function playSong(song){if(!song)return;state.playerSong=song;state.selectedSong=song.id;state.playing=true;state.seconds=0;$('#player-cover').src=imageOr(song.cover);$('#player-bar').style.setProperty('--player-art',`url("${imageOr(song.cover)}")`);$('#player-title').textContent=song.title;$('#player-artist').textContent=song.collaborators?`${state.profile.name} · feat. ${song.collaborators}`:state.profile.name;$('#total-time').textContent='3:00';$('#play-toggle').textContent='Ⅱ';if(song.sessionAudio||song.audioUrl){if(window.currentAudio)window.currentAudio.pause();window.currentAudio=new Audio(song.sessionAudio||song.audioUrl);window.currentAudio.onloadedmetadata=()=>{$('#total-time').textContent=Number.isFinite(window.currentAudio.duration)?fmtTime(window.currentAudio.duration):'3:00';$('#seek').value=0};window.currentAudio.play().catch(()=>{});window.currentAudio.ontimeupdate=()=>{state.seconds=window.currentAudio.currentTime;$('#elapsed').textContent=fmtTime(state.seconds);$('#seek').value=window.currentAudio.duration?100*state.seconds/window.currentAudio.duration:0};window.currentAudio.onended=()=>{state.playing=false;$('#play-toggle').textContent='▶'}}else{clearInterval(timer);state.playing=false;$('#play-toggle').textContent='▶';$('#elapsed').textContent='0:00';$('#seek').value=0}toast((song.sessionAudio||song.audioUrl)?`Reproduciendo ${song.title}`:'Agrega el audio para escuchar esta canción')}
function togglePlay(){if(!state.playerSong){const s=sortedSongs(state.songs.filter(x=>x.published))[0];if(s)playSong(s);else toast('Publica una canción para escucharla');return}if(!window.currentAudio){toast('Agrega el audio para escuchar esta canción');return}state.playing=!state.playing;$('#play-toggle').textContent=state.playing?'Ⅱ':'▶';if(window.currentAudio){state.playing?window.currentAudio.play().catch(()=>{}):window.currentAudio.pause()}}
function bindViewEvents(){ $$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$$('[data-action="new-song"]').forEach(b=>b.onclick=()=>songEditor());$$('[data-action="new-project"]').forEach(b=>b.onclick=()=>projectEditor());$$('[data-mode]').forEach(b=>b.onclick=()=>{state.catalogMode=b.dataset.mode;render()});const search=$('#catalog-search');if(search){search.oninput=()=>{state.catalogSearch=search.value;const pos=search.selectionStart;render();$('#catalog-search').focus();$('#catalog-search').setSelectionRange(pos,pos)}}const filter=$('#catalog-filter');if(filter){filter.value=state.catalogFilter;filter.onchange=()=>{state.catalogFilter=filter.value;render()}}const sort=$('#catalog-sort');if(sort){sort.value=state.catalogSort;sort.onchange=()=>{state.catalogSort=sort.value;render()}}const ps=$('#project-search');if(ps)ps.oninput=()=>{state.projectSearch=ps.value;const pos=ps.selectionStart;render();$('#project-search').focus();$('#project-search').setSelectionRange(pos,pos)};$$('[data-song]').forEach(el=>el.addEventListener('click',e=>{if(e.target.closest('button'))return;songEditor(el.dataset.song)}));$$('[data-edit-song]').forEach(b=>b.onclick=e=>{e.stopPropagation();songEditor(b.dataset.editSong)});$$('[data-edit-project]').forEach(b=>b.onclick=()=>projectEditor(b.dataset.editProject));$$('[data-play]').forEach(b=>b.onclick=e=>{e.stopPropagation();playSong(songById(b.dataset.play))});$$('[data-play-published]').forEach(b=>b.onclick=()=>{const s=sortedSongs(state.songs.filter(x=>x.published))[0];playSong(s)});$$('[data-platform]').forEach(b=>b.onclick=()=>{state.platform=b.dataset.platform;state.simPage='profile';setView('spotify')});$$('[data-sim-page]').forEach(b=>b.onclick=()=>{state.simPage=b.dataset.simPage;render()});$$('[data-song-view]').forEach(el=>el.onclick=e=>{if(e.target.closest('button'))return;state.selectedSong=el.dataset.songView;state.simPage='song';render()});$$('[data-sim-project]').forEach(b=>b.onclick=()=>projectModal(b.dataset.simProject));$$('[data-action="save-profile"]').forEach(b=>b.onclick=saveProfile);$('#profile-avatar')?.addEventListener('change',e=>prepareImageInput(e.target,1,'#profile-avatar-preview'));$('#profile-banner')?.addEventListener('change',e=>prepareImageInput(e.target,3,'#profile-banner-preview'));$('#dark-switch')?.addEventListener('change',e=>{state.settings.dark=e.target.checked;document.body.classList.toggle('dark-off',!e.target.checked);persistLocal()});$$('[data-action="account"]').forEach(b=>b.onclick=accountModal);$$('[data-action="reset-demo"]').forEach(b=>b.onclick=resetDemo)}
function projectModal(id){const p=state.projects.find(x=>x.id===id);if(!p)return;state.selectedSong=null;state.simPage='profile';const tracks=(p.trackIds||[]).map(songById).filter(Boolean);showModal(escapeHtml(p.title),`<div class="edit-layout"><img class="edit-cover" src="${imageOr(p.cover)}"><div><div class="eyebrow">${p.published?'PROYECTO PUBLICADO':'PROYECTO'}</div><h3 style="font-size:22px">${escapeHtml(p.title)}</h3><p class="table-muted">${dateLabel(p.releaseDate)} · ${escapeHtml(p.collaborators||state.profile.name)}</p><p class="table-muted">${escapeHtml(p.description||'')}</p><h3 style="margin-top:25px">Tracks · ${tracks.length}</h3>${tracks.map(songRow).join('')}</div></div>`,`<span></span><div class="button-row"><button class="button" data-close>Listo</button><button class="button primary" data-edit-project-modal>Editar proyecto</button></div>`);$('[data-edit-project-modal]').onclick=()=>projectEditor(id)}
async function prepareImageInput(input,aspect,previewSelector,statusSelector='#image-upload-status'){const file=input.files?.[0];if(!file)return null;input.dataset.uploading='true';delete input.dataset.uploadedUrl;delete input.dataset.uploadError;const status=$(statusSelector);if(status)status.textContent='Preparando imagen…';try{const cropped=await cropImageFile(file,aspect);if(!cropped){input.value='';input.dataset.uploading='false';const preview=$(previewSelector);if(preview){const fallback=input.id.toLowerCase().includes('avatar')?state.profile.avatar:state.profile.banner;preview.src=fallback||COVER;preview.hidden=Boolean(input.id.toLowerCase().includes('banner')&&!fallback)}if(status)status.textContent='';return null}const url=state.storage&&state.user?await uploadProfile(cropped,statusSelector):await blobToData(cropped);if(!url)throw new Error('No se pudo generar la imagen');input.dataset.uploadedUrl=url;const preview=$(previewSelector);if(preview){preview.src=url;preview.hidden=false}input.dataset.uploading='false';if(status)status.textContent='Imagen lista para guardar';return url}catch(error){console.error(error);input.dataset.uploading='false';input.dataset.uploadError='true';if(status)status.textContent='Error al subir. Revisa Firebase Storage e inténtalo otra vez.';toast(error.code==='storage/unauthorized'?'Firebase Storage rechazó el archivo. Revisa sus reglas.':'No se pudo subir la imagen. Inténtalo otra vez.');return null}}
async function saveProfile(){const name=$('#profile-name').value.trim();if(!name){toast('Escribe un nombre de artista');return}state.profile.name=name;state.profile.bio=$('#profile-bio').value;const av=$('#profile-avatar'),bn=$('#profile-banner');if(av.dataset.uploading==='true'||bn.dataset.uploading==='true'){toast('Espera a que terminen las cargas');return}if(av.dataset.uploadError==='true'||bn.dataset.uploadError==='true'){toast('No se guardó el perfil porque una imagen no pudo cargarse.');return}const avatarUrl=av.dataset.uploadedUrl||null,bannerUrl=bn.dataset.uploadedUrl||null;if(avatarUrl)state.profile.avatar=avatarUrl;if(bannerUrl)state.profile.banner=bannerUrl;identity();persistLocal();if(state.db&&state.user)await cloudSave('profile',{id:'main',...state.profile});state.songs.forEach(s=>s.artist=name);state.projects.forEach(p=>p.artist=name);render();toast('Perfil actualizado')}
async function fileToData(file,aspect=1){if(!file)return null;const cropped=await cropImageFile(file,aspect);if(!cropped)return null;if(state.storage&&state.user)return uploadProfile(cropped);return blobToData(cropped)}
function blobToData(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)})}
async function uploadProfile(file,statusSelector='#upload-status'){const {ref,uploadBytesResumable,getDownloadURL}=await import('https://www.gstatic.com/firebasejs/11.0.2/firebase-storage.js');const path=`users/${state.user.uid}/images/profile-${Date.now()}-${file.name.replace(/[^\w.-]/g,'_')}`;const task=uploadBytesResumable(ref(state.storage,path),file,{contentType:file.type});toast('Subiendo imagen…');await new Promise((resolve,reject)=>task.on('state_changed',snapshot=>{const percent=Math.round(snapshot.bytesTransferred/snapshot.totalBytes*100);const status=$(statusSelector);if(status)status.textContent=`Subiendo… ${percent}%`},reject,resolve));return getDownloadURL(task.snapshot.ref)}
function renderAuthGate(configMessage=''){const root=$('#auth-root');$('#app').hidden=true;const signup=state.authMode==='signup';const firebaseReady=Boolean(state.auth);root.innerHTML=`<main class="auth-page"><section class="auth-story"><div class="auth-story-content"><div class="auth-mark"><img src="./assets/cholos-logo.png" alt=""><span>Cholos in Paris</span></div><div class="auth-copy"><span class="eyebrow">TU MÚSICA, EN UN SOLO LUGAR</span><h1>${signup?'Empieza a crear':'Qué bueno verte de nuevo'}</h1><p>${signup?'Organiza tus canciones, construye proyectos y prepara cada lanzamiento.':'Entra a tu espacio de artista y continúa donde lo dejaste.'}</p><div class="auth-steps"><div class="auth-step active"><b>01</b><span>${signup?'Crea tu cuenta':'Inicia sesión'}</span></div><div class="auth-step"><b>02</b><span>Configura tu espacio</span></div><div class="auth-step"><b>03</b><span>Prepara tu música</span></div></div></div><div class="auth-story-footer">CHOLOS IN PARIS <span>·</span> ESPACIO DE ARTISTA</div></section><section class="auth-form-side"><form class="auth-form" id="auth-form"><div class="auth-mobile-mark"><img src="./assets/cholos-logo.png" alt=""></div><span class="eyebrow">${signup?'NUEVA CUENTA':'ACCESO DE ARTISTA'}</span><h2>${signup?'Crear cuenta':'Iniciar sesión'}</h2><p class="auth-subtitle">${signup?'Regístrate para abrir tu espacio privado.':'Ingresa para continuar a tu espacio.'}</p><div class="auth-providers"><button type="button" class="provider-button" data-auth="google"><span class="google-g">G</span><span>Google</span></button><button type="button" class="provider-button" data-auth="apple"><span class="apple-mark">A</span><span>Apple</span></button></div><div class="auth-divider"><span>o con correo electrónico</span></div><div class="field auth-name-field" ${signup?'':'hidden'}><label for="auth-name">Nombre (opcional)</label><input id="auth-name" autocomplete="name" placeholder="Tu nombre"></div><div class="field"><label for="auth-email">Correo electrónico</label><input id="auth-email" type="email" autocomplete="email" required placeholder="nombre@correo.com"></div><div class="field"><label for="auth-password">Contraseña</label><input id="auth-password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="6" required placeholder="${signup?'Mínimo 6 caracteres':'Tu contraseña'}"></div><div class="auth-error" id="auth-error" role="alert">${escapeHtml(configMessage)}</div><button class="button primary auth-submit" type="submit">${signup?'Crear cuenta':'Entrar a mi espacio'} <span>→</span></button><p class="auth-switch">${signup?'¿Ya tienes una cuenta?':'¿Primera vez por aquí?'} <button type="button" id="auth-mode-toggle">${signup?'Inicia sesión':'Crea tu cuenta'}</button></p><p class="auth-privacy">Tu catálogo es privado y solo tú puedes acceder.</p></form></section></main>`;$('#auth-form').addEventListener('submit',e=>{e.preventDefault();authAction(signup?'email-signup':'email-login')});$$('[data-auth]',root).forEach(button=>button.onclick=()=>authAction(button.dataset.auth));$('#auth-mode-toggle').onclick=()=>{state.authMode=signup?'login':'signup';renderAuthGate(configMessage)}}
function setAuthenticatedView(user){$('#auth-root').innerHTML='';$('#app').hidden=!user}
function authError(message){const node=$('#auth-error');if(node)node.textContent=message;else toast(message)}
function accountModal(){const body=`<p class="table-muted" style="line-height:1.7">Sesión iniciada con ${escapeHtml(state.user?.email||state.user?.displayName||'Firebase')}.</p><div class="panel" style="display:grid;gap:9px"><button class="button danger" data-auth="signout">Cerrar sesión</button></div>`;showModal('Cuenta y acceso',body,'<span></span><button class="button" data-close>Listo</button>');$$('[data-auth]').forEach(b=>b.onclick=()=>authAction(b.dataset.auth))}
function onboardingModal(){const body=`<p class="table-muted" style="line-height:1.6">Prepara tu perfil público. Estos datos aparecerán en las vistas de tus plataformas simuladas.</p><div class="form-grid"><div class="field full"><label>Nombre de artista *</label><input id="onboard-name" value="${escapeHtml(state.profile.name)}" placeholder="Tu nombre artístico"></div><div class="field"><label>Foto de perfil</label><label class="file-picker">＋ Foto de artista<input type="file" id="onboard-avatar" accept="image/*"></label><img class="profile-upload-preview" id="onboard-avatar-preview" src="${state.profile.avatar||COVER}" alt="Vista previa de foto"></div><div class="field"><label>Banner</label><label class="file-picker">＋ Banner<input type="file" id="onboard-banner" accept="image/*"></label><img class="profile-upload-preview banner-upload-preview" id="onboard-banner-preview" src="${state.profile.banner||COVER}" alt="Vista previa de banner"></div></div><small id="onboard-upload-status" class="upload-status"></small>`;showModal('Tu perfil de artista',body,'<span class="table-muted">Lo puedes editar después en Perfil.</span><button class="button primary" data-onboard-save>Empezar →</button>');$('#onboard-avatar')?.addEventListener('change',e=>prepareImageInput(e.target,1,'#onboard-avatar-preview','#onboard-upload-status'));$('#onboard-banner')?.addEventListener('change',e=>prepareImageInput(e.target,3,'#onboard-banner-preview','#onboard-upload-status'));$('[data-onboard-save]').onclick=async()=>{const name=$('#onboard-name').value.trim();if(!name){toast('Escribe tu nombre de artista');return}state.profile.name=name;const av=$('#onboard-avatar'),bn=$('#onboard-banner');if(av.dataset.uploading==='true'||bn.dataset.uploading==='true'){toast('Espera a que terminen las cargas');return}if(av.dataset.uploadError==='true'||bn.dataset.uploadError==='true'){toast('No se guardó el perfil porque una imagen no pudo cargarse.');return}const avatarUrl=av.dataset.uploadedUrl||null,bannerUrl=bn.dataset.uploadedUrl||null;if(avatarUrl)state.profile.avatar=avatarUrl;if(bannerUrl)state.profile.banner=bannerUrl;await cloudSave('profile',{id:'main',...state.profile});identity();closeModal();render();toast('Tu espacio está listo')}}
async function authAction(action){if(!state.auth){authError('Configura los datos de Firebase en firebase-config.js para activar el acceso.');return}try{const A=await import('https://www.gstatic.com/firebasejs/11.0.2/firebase-auth.js');if(action==='google'){await A.signInWithPopup(state.auth,new A.GoogleAuthProvider())}else if(action==='apple'){await A.signInWithPopup(state.auth,new A.OAuthProvider('apple.com'))}else if(action==='email-signup'){await A.createUserWithEmailAndPassword(state.auth,$('#auth-email').value.trim(),$('#auth-password').value)}else if(action==='email-login'){await A.signInWithEmailAndPassword(state.auth,$('#auth-email').value.trim(),$('#auth-password').value)}else if(action==='signout'){await A.signOut(state.auth)}closeModal()}catch(e){const messages={'auth/email-already-in-use':'Ese correo ya tiene una cuenta. Inicia sesión.','auth/invalid-email':'Revisa el formato del correo.','auth/invalid-credential':'El correo o la contraseña no coinciden.','auth/weak-password':'Usa una contraseña de al menos 6 caracteres.','auth/popup-closed-by-user':'Se cerró la ventana de acceso.','auth/unauthorized-domain':'Agrega este dominio a los dominios autorizados de Firebase.'};authError(messages[e.code]||e.message||'No se pudo completar el acceso')}}
function resetDemo(){if(!confirm('¿Restablecer el catálogo de demostración? Esto reemplaza los datos locales actuales.'))return;localStorage.removeItem('chip-studio-state');location.reload()}

async function initFirebase(){if(!firebaseConfig.apiKey||firebaseConfig.apiKey.startsWith('PEGA_')){renderAuthGate('Completa firebase-config.js para activar registro e inicio de sesión.');return}try{const [App,Auth,Store,Storage]=await Promise.all(['app','auth','firestore','storage'].map(s=>import(`https://www.gstatic.com/firebasejs/11.0.2/firebase-${s}.js`)));const app=App.initializeApp(firebaseConfig);state.auth=Auth.getAuth(app);state.db=Store.getFirestore(app);state.storage=Storage.getStorage(app);Auth.onAuthStateChanged(state.auth,async user=>{state.user=user;if(user){setAuthenticatedView(user);const ready=await loadCloud();$('#save-state').textContent='Sincronizado con Firebase';identity();render();if(!ready)onboardingModal()}else{setAuthenticatedView(null);state.songs=[];state.projects=[];state.profile={name:'',bio:'',avatar:'',banner:''};renderAuthGate()}})}catch(e){console.error('Firebase no pudo inicializarse',e);renderAuthGate('Firebase no pudo iniciar. Revisa firebase-config.js.')}}
async function cloudSave(collection,record){if(!state.db||!state.user)return;try{const {doc,setDoc}=await import('https://www.gstatic.com/firebasejs/11.0.2/firebase-firestore.js');const {sessionAudio,...clean}=record;if(clean.versions)clean.versions=clean.versions.map(({sessionAudio,...version})=>version);await setDoc(doc(state.db,'users',state.user.uid,collection,record.id),clean);$('#save-state').textContent='Sincronizado'}catch(e){console.error(e);$('#save-state').textContent='Error al sincronizar'}}
async function loadCloud(){try{const {collection,getDocs,doc,getDoc}=await import('https://www.gstatic.com/firebasejs/11.0.2/firebase-firestore.js');const [songs,projects,profile]=await Promise.all([getDocs(collection(state.db,'users',state.user.uid,'songs')),getDocs(collection(state.db,'users',state.user.uid,'projects')),getDoc(doc(state.db,'users',state.user.uid,'profile','main'))]);state.songs=songs.docs.map(d=>{const song=d.data();delete song.duration;return song});state.projects=projects.docs.map(d=>d.data());if(profile.exists()){state.profile={...state.profile,...profile.data()};persistLocal();return true}state.profile={name:state.user.displayName||'',bio:'',avatar:'',banner:''};return false}catch(e){console.error(e);toast('No se pudieron cargar tus datos de Firebase');return true}}
function bindGlobal(){$$('.nav-item[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#mobile-menu').onclick=()=>{const open=$('.sidebar').classList.toggle('open');$('#mobile-menu').setAttribute('aria-expanded',String(open))};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('.sidebar').classList.remove('open')});$('#theme-toggle').onclick=()=>{state.settings.dark=!state.settings.dark;document.body.classList.toggle('dark-off',!state.settings.dark);persistLocal()};$('#play-toggle').onclick=togglePlay;$('#prev-track').onclick=()=>{const a=sortedSongs(state.songs.filter(s=>s.published));const i=a.findIndex(s=>s.id===state.playerSong?.id);if(a.length)playSong(a[(i-1+a.length)%a.length])};$('#next-track').onclick=()=>{const a=sortedSongs(state.songs.filter(s=>s.published));const i=a.findIndex(s=>s.id===state.playerSong?.id);if(a.length)playSong(a[(i+1)%a.length])};$('#seek').oninput=e=>{const s=state.playerSong;if(window.currentAudio&&Number.isFinite(window.currentAudio.duration)){window.currentAudio.currentTime=window.currentAudio.duration*e.target.value/100;state.seconds=window.currentAudio.currentTime;$('#elapsed').textContent=fmtTime(state.seconds)}else toast('Sube un audio para desplazarte por la canción')};$('#lyrics-open').onclick=()=>{if(!state.playerSong){toast('Elige una canción primero');return}showModal(`Letra · ${escapeHtml(state.playerSong.title)}`,`<div style="white-space:pre-line;line-height:2;font-size:17px">${escapeHtml(state.playerSong.lyrics||'Aún no hay letra guardada.')}</div>`,'<span></span><button class="button" data-close>Cerrar</button>')};$('#queue-open').onclick=()=>showModal('Cola de reproducción',sortedSongs(state.songs.filter(s=>s.published)).map((s,i)=>`<div class="version-row"><span class="version-number">${i+1}</span><div><strong>${escapeHtml(s.title)}</strong><small>${dateLabel(s.releaseDate)}</small></div><button class="small-icon" data-queue-play="${s.id}">▶</button></div>`).join('')||'<p class="table-muted">No hay canciones publicadas.</p>','<span></span><button class="button" data-close>Listo</button>');$('#expand-player').onclick=()=>{if(!state.playerSong){toast('Elige una canción primero');return}state.platform='Spotify';state.simPage='player';setView('spotify')};document.addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeModal();const b=e.target.closest('[data-queue-play]');if(b)playSong(songById(b.dataset.queuePlay))});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()})}
function songModal(s){state.platform='Spotify';state.simPage='song';state.selectedSong=s.id;setView('spotify')}
function boot(){document.body.classList.remove('dark-off');$('#app').hidden=true;bindGlobal();renderAuthGate();initFirebase()}
function renderPlatform(platform){
  const songs=sortedSongs(state.songs.filter(song=>song.published));
  const projects=sortedSongs(state.projects.filter(project=>project.published));
  const key=platform==='Apple Music'?'apple-music':platform==='YouTube'?'youtube':platform==='SoundCloud'?'soundcloud':'spotify';
  document.body.dataset.preview=key;
  const page=renderPlatformPage(platform,songs,projects);
  return `<section class="sim-shell sim-${key}"><header class="sim-preview-bar"><div class="preview-id"><span class="preview-live"></span><span>PREVISUALIZACIÓN</span><b>${escapeHtml(platform)}</b></div><button class="preview-exit" data-view="catalog">Volver al catálogo <span>↗</span></button></header>${page}</section>`;
}
function youtubeReleaseCards(){const projects=state.projects.filter(item=>item.published).map(project=>'<button class="yt-release" data-sim-project="'+project.id+'"><span class="yt-release-art" style="--release-art:url('+String.fromCharCode(39)+imageOr(project.cover)+String.fromCharCode(39)+')"><img src="'+imageOr(project.cover)+'" alt=""><b>▶</b></span><strong>'+escapeHtml(project.title)+'</strong><small>Álbum · '+escapeHtml(state.profile.name)+'</small></button>');const songs=state.songs.filter(item=>item.published).map(song=>'<button class="yt-release" data-play="'+song.id+'"><span class="yt-release-art" style="--release-art:url('+String.fromCharCode(39)+imageOr(song.cover)+String.fromCharCode(39)+')"><img src="'+imageOr(song.cover)+'" alt=""><b>▶</b></span><strong>'+escapeHtml(song.title)+'</strong><small>Sencillo · '+dateLabel(song.releaseDate)+'</small></button>');return projects.concat(songs).join('')||'<p class="platform-empty">Los lanzamientos aparecerán aquí al publicar.</p>'}
function renderPlatformPage(platform,songs,projects){
  const songRows=(items=songs)=>items.map((song,index)=>`<div class="platform-track" data-sim-song="${song.id}"><span class="track-index">${String(index+1).padStart(2,'0')}</span><img src="${imageOr(song.cover)}" alt=""><div class="platform-track-copy"><strong>${escapeHtml(song.title)}</strong><small>${escapeHtml(song.collaborators?`${state.profile.name} · feat. ${song.collaborators}`:state.profile.name)}</small></div><span class="platform-track-date">${dateLabel(song.releaseDate)}</span><button class="platform-track-play" data-play="${song.id}" aria-label="Reproducir ${escapeHtml(song.title)}">▶</button></div>`).join('')||'<p class="platform-empty">Aún no hay canciones publicadas.</p>';
  const projectCards=(items=projects)=>items.map(project=>`<button class="platform-release" data-sim-project="${project.id}"><img src="${imageOr(project.cover)}" alt=""><strong>${escapeHtml(project.title)}</strong><span>${new Date(`${project.releaseDate||today}T12:00:00`).getFullYear()} · Álbum</span></button>`).join('')||'<p class="platform-empty">Los proyectos publicados aparecerán aquí.</p>';
  const artist=escapeHtml(state.profile.name||'Artista');
  const avatar=imageOr(state.profile.avatar,COVER);
  const pageHeader=(label,title,description='')=>`<div class="platform-page-head"><span>${label}</span><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>`;
  let inside='';
  if(state.simPage==='profile'){
    if(platform==='Spotify') inside=`<div class="spotify-layout"><aside class="spotify-left"><div class="spotify-wordmark">Música<span>●</span></div><button class="spotify-side-item active">⌂ <span>Inicio</span></button><button class="spotify-side-item">⌕ <span>Buscar</span></button><button class="spotify-side-item">▤ <span>Tu biblioteca</span></button><div class="spotify-library"><small>DISCOTECA</small><button data-sim-page="discography">Discografía</button><button data-sim-page="queue">Cola de reproducción</button></div></aside><main class="spotify-main"><section class="spotify-artist sim-hero" style="--artist-banner:url('${state.profile.banner||''}')"><img src="${avatar}" alt=""><div><small>ARTISTA</small><h1>${artist}</h1><p>${songs.length} canciones · ${projects.length} álbumes</p></div></section><div class="spotify-actions"><button class="spotify-green-play" data-play-published>▶</button><button class="spotify-follow">Seguir</button><button class="spotify-more">•••</button></div><section class="platform-section"><div class="platform-section-heading"><h2>Canciones populares</h2><button data-sim-page="discography">Ver discografía</button></div>${songs.slice(0,5).map((song,index)=>`<div class="platform-track" data-sim-song="${song.id}"><span class="track-index">${String(index+1).padStart(2,'0')}</span><img src="${imageOr(song.cover)}" alt=""><div class="platform-track-copy"><strong>${escapeHtml(song.title)}</strong><small>${escapeHtml(song.collaborators?`${artist} · feat. ${song.collaborators}`:artist)}</small></div><span class="platform-track-date">${dateLabel(song.releaseDate)}</span><button class="platform-track-play" data-play="${song.id}">▶</button></div>`).join('')||'<p class="platform-empty">Publica tu primera canción y aparecerá aquí.</p>'}</section><section class="platform-section"><div class="platform-section-heading"><h2>Discografía</h2><button data-sim-page="discography">Mostrar todo</button></div><div class="platform-release-grid yt-release-grid">${youtubeReleaseCards()}</div></section></main></div>`;
    else if(platform==='Apple Music') inside=`<div class="apple-app"><header class="apple-nav"><span class="apple-music-mark">♫</span><strong>Música</strong><nav><button>Inicio</button><button>Explorar</button><button>Radio</button></nav><button class="apple-account">Cuenta</button></header><main class="apple-main"><section class="apple-artist sim-hero"><img src="${avatar}" alt=""><div><span>ARTISTA</span><h1>${artist}</h1><p>${songs.length} canciones · ${projects.length} álbumes</p><button class="apple-play" data-play-published>▶ Reproducir</button><button class="apple-shuffle">Aleatorio</button></div></section><div class="apple-tabs"><button class="selected">Todo</button><button data-sim-page="discography">Álbumes</button><button data-sim-page="discography">Sencillos</button></div><section class="platform-section"><div class="platform-section-heading"><h2>Populares</h2><button data-sim-page="discography">Ver discografía</button></div>${songs.slice(0,5).map((song,index)=>`<div class="platform-track" data-sim-song="${song.id}"><span class="track-index">${index+1}</span><img src="${imageOr(song.cover)}" alt=""><div class="platform-track-copy"><strong>${escapeHtml(song.title)}</strong><small>${escapeHtml(song.collaborators?`${artist} · feat. ${song.collaborators}`:artist)}</small></div><span class="platform-track-date">${dateLabel(song.releaseDate)}</span><button class="platform-track-play" data-play="${song.id}">▶</button></div>`).join('')||'<p class="platform-empty">Publica canciones para verlas aquí.</p>'}</section><section class="platform-section"><div class="platform-section-heading"><h2>Álbumes y sencillos</h2></div><div class="platform-release-grid">${projectCards()}</div></section></main><footer class="apple-mini-player"><img src="${imageOr(state.playerSong?.cover)}"><div><strong>${escapeHtml(state.playerSong?.title||'Elige una canción')}</strong><small>${artist}</small></div><button data-play-published>▶</button><button data-sim-page="queue">☷</button></footer></div>`;
    else if(platform==='YouTube') inside=`<div class="youtube-app"><header class="youtube-nav"><span class="yt-menu">☰</span><span class="yt-mark">▶</span><strong>YouTube</strong><label>⌕ <span>Buscar música</span></label><button>⋮</button></header><main><section class="youtube-artist sim-hero"><img class="yt-artist-avatar" src="${avatar}" alt=""><div><span>CANAL OFICIAL DEL ARTISTA</span><h1>${artist}</h1><p>${songs.length} canciones · ${projects.length} álbumes</p><button class="yt-play-all" data-play-published>▶ Reproducir todo</button><button class="yt-shuffle">Aleatorio</button></div></section><div class="youtube-tabs"><button class="selected">Inicio</button><button data-sim-page="discography">Lanzamientos</button><button>Videos</button></div><section class="platform-section"><div class="platform-section-heading"><h2>Canciones populares</h2><button data-sim-page="discography">Ver todo</button></div>${songs.slice(0,5).map((song,index)=>`<div class="platform-track" data-sim-song="${song.id}"><span class="track-index">${index+1}</span><img src="${imageOr(song.cover)}" alt=""><div class="platform-track-copy"><strong>${escapeHtml(song.title)}</strong><small>${artist}${song.collaborators?' · '+escapeHtml(song.collaborators):''}</small></div><span class="platform-track-date">${dateLabel(song.releaseDate)}</span><button class="platform-track-play" data-play="${song.id}">▶</button></div>`).join('')||'<p class="platform-empty">No hay lanzamientos públicos todavía.</p>'}</section><section class="platform-section"><div class="platform-section-heading"><h2>Discografía</h2><button data-sim-page="discography">Ver más</button></div><div class="platform-release-grid">${projectCards()}</div></section></main></div>`;
    else inside=`<div class="soundcloud-app"><header class="soundcloud-nav"><span class="sc-symbol">≋</span><strong>SoundCloud</strong><button>Inicio</button><button>Feed</button><button>Biblioteca</button><label>⌕ <span>Buscar</span></label></header><main><section class="soundcloud-artist sim-hero"><div class="sc-banner" style="background-image:linear-gradient(90deg,#0007,transparent),url('${state.profile.banner||''}')"><img src="${avatar}" alt=""><div><h1>${artist}</h1><p>${songs.length} canciones · ${projects.length} proyectos</p><button class="sc-follow">Seguir</button><button class="sc-play" data-play-published>▶ Reproducir</button></div></div></section><div class="soundcloud-columns"><section class="platform-section"><div class="platform-section-heading"><h2>Tracks</h2><button data-sim-page="discography">Ver discografía</button></div>${songs.slice(0,8).map((song,index)=>`<div class="sc-track platform-track" data-sim-song="${song.id}"><span class="track-index">${index+1}</span><img src="${imageOr(song.cover)}" alt=""><div class="platform-track-copy"><strong>${escapeHtml(song.title)}</strong><small>${dateLabel(song.releaseDate)} · ${artist}${song.collaborators?' feat. '+escapeHtml(song.collaborators):''}</small><div class="waveform" aria-hidden="true"></div></div><button class="platform-track-play" data-play="${song.id}">▶</button></div>`).join('')||'<p class="platform-empty">Tus tracks publicados aparecerán aquí.</p>'}</section><aside class="platform-section sc-releases"><h2>Discografía</h2>${projectCards()}</aside></div></main></div>`;
  } else if(state.simPage==='discography'){
    const showSongs=state.simFilter!=='albums',showProjects=state.simFilter!=='songs';
    inside=`<div class="platform-subpage">${pageHeader(platform.toUpperCase(),'Discografía',artist)}<div class="platform-subnav"><button data-sim-page="profile">← Perfil del artista</button><button data-sim-filter="songs">Canciones</button><button data-sim-filter="albums">Álbumes</button><button data-sim-filter="all">Todo</button></div>${showSongs?`<section class="platform-section"><h2>Canciones</h2><div class="platform-track-list">${songRows()}</div></section>`:''}${showProjects?`<section class="platform-section"><h2>Álbumes y EPs</h2><div class="platform-release-grid">${projectCards()}</div></section>`:''}</div>`;
  } else if(state.simPage==='song'){
    const song=songById(state.selectedSong);if(!song)return `<div class="platform-subpage">${pageHeader(platform.toUpperCase(),'La canción ya no está publicada')}<button class="button" data-sim-page="profile">Volver</button></div>`;
    inside=`<div class="platform-detail"><button class="platform-back" data-sim-page="profile">← ${artist}</button><div class="platform-detail-hero"><img src="${imageOr(song.cover)}" alt=""><div><span>CANCIÓN · ${dateLabel(song.releaseDate)}</span><h1>${escapeHtml(song.title)}</h1><p>${artist}${song.collaborators?' · feat. '+escapeHtml(song.collaborators):''}</p><button class="detail-play" data-play="${song.id}">▶ Reproducir</button><button data-sim-page="lyrics">Ver letra</button><button data-sim-page="queue">Cola</button></div></div><section class="platform-section"><h2>Créditos</h2><p>${artist}${song.collaborators?' · '+escapeHtml(song.collaborators):''}</p><p>Publicado el ${dateLabel(song.releaseDate)}</p></section></div>`;
  } else if(state.simPage==='album'){
    const project=state.projects.find(item=>item.id===state.selectedProject);if(!project)return `<div class="platform-subpage">${pageHeader(platform.toUpperCase(),'Proyecto no disponible')}<button data-sim-page="profile">Volver</button></div>`;
    const tracks=(project.trackIds||[]).map(songById).filter(Boolean);
    inside=`<div class="platform-detail"><button class="platform-back" data-sim-page="discography">← Discografía</button><div class="platform-detail-hero album-detail-hero"><img src="${imageOr(project.cover)}" alt=""><div><span>ÁLBUM · ${new Date(`${project.releaseDate}T12:00:00`).getFullYear()}</span><h1>${escapeHtml(project.title)}</h1><p>${artist}${project.collaborators?' · '+escapeHtml(project.collaborators):''}</p><button class="detail-play" data-play-album>▶ Reproducir</button><button data-sim-page="queue">Cola</button></div></div><section class="platform-section"><h2>Canciones</h2>${tracks.map((song,index)=>`<div class="platform-track" data-sim-song="${song.id}"><span class="track-index">${index+1}</span><img src="${imageOr(project.cover,song.cover)}" alt=""><div class="platform-track-copy"><strong>${escapeHtml(song.title)}</strong><small>${artist}${song.collaborators?' · feat. '+escapeHtml(song.collaborators):''}</small></div><span class="platform-track-date">${song.audioUrl?'Audio':'3:00'}</span><button class="platform-track-play" data-play="${song.id}">▶</button></div>`).join('')}</section></div>`;
  } else if(state.simPage==='lyrics'){
    const song=state.playerSong||songById(state.selectedSong);inside=`<div class="platform-subpage lyrics-surface"><button class="platform-back" data-sim-page="song">← Volver a la canción</button><div class="lyrics-preview"><img src="${imageOr(song?.cover)}" alt=""><span>LETRA</span><h1>${escapeHtml(song?.title||'Elige una canción')}</h1><p>${artist}</p><div>${escapeHtml(song?.lyrics||'La letra de esta canción todavía no se ha agregado.').replace(/\n/g,'<br>')}</div></div></div>`;
  } else if(state.simPage==='queue'){
    inside=`<div class="platform-subpage">${pageHeader('EN REPRODUCCIÓN','Cola de reproducción',escapeHtml(state.playerSong?.title||'Tu música publicada'))}<button class="platform-back" data-sim-page="profile">← Perfil del artista</button><section class="platform-section"><h2>A continuación</h2>${songRows()}</section></div>`;
  } else {
    const song=state.playerSong||songs[0];inside='<div class="platform-subpage extended-player full-player" style="--player-art:url(\''+imageOr(song?.cover)+'\')"><button class="platform-back" data-sim-page="profile">⌄ Cerrar reproductor</button><div class="player-art-stage"><div class="player-art-glow"></div><img class="player-artwork" src="'+imageOr(song?.cover)+'" alt="Portada del álbum"></div><div class="player-now-copy"><span>REPRODUCIENDO EN '+platform.toUpperCase()+'</span><h1>'+escapeHtml(song?.title||'Elige una canción')+'</h1><p>'+artist+(song?.collaborators?' · feat. '+escapeHtml(song.collaborators):'')+'</p></div><div class="full-player-controls"><div class="full-seek-row"><span id="expanded-elapsed">'+fmtTime(state.seconds||0)+'</span><input id="expanded-seek" type="range" min="0" max="100" value="0" aria-label="Posición de reproducción"><span id="expanded-total">3:00</span></div><div class="transport-controls"><button data-player-prev aria-label="Anterior">|◀</button><button class="transport-play" data-player-toggle aria-label="Reproducir o pausar">'+(state.playing?'Ⅱ':'▶')+'</button><button data-player-next aria-label="Siguiente">▶|</button></div><div class="player-utility-controls"><button data-sim-page="lyrics">♫ Letra</button><button data-sim-page="queue">☷ Cola</button><label>◖<input type="range" min="0" max="1" step="0.01" value="0.8" id="player-volume" aria-label="Volumen"></label><button data-sim-page="player" aria-label="Pantalla completa">⛶</button></div></div></div>'
  }
  return `<div class="platform-frame"><header class="platform-head"><span class="platform-head-name">${escapeHtml(platform)}</span><span class="platform-head-note">VISTA PREVIA DE ARTISTA</span><button class="platform-back-icon" data-view="catalog" aria-label="Volver">×</button></header>${inside}</div>`;
}
function attachGlobalSearch(){const input=$('#global-search'),results=$('#global-search-results');if(!input||!results)return;input.addEventListener('input',()=>{const query=input.value.trim().toLowerCase();if(!query){results.innerHTML='';results.classList.remove('open');return}const songs=sortedSongs(state.songs.filter(s=>[s.title,s.collaborators,s.artist].join(' ').toLowerCase().includes(query))).slice(0,5);const projects=state.projects.filter(p=>p.title.toLowerCase().includes(query)).slice(0,3);results.innerHTML=[...songs.map(s=>`<button data-global-song="${s.id}"><img src="${imageOr(s.cover)}"><span>${escapeHtml(s.title)}<small>Canción · ${dateLabel(s.releaseDate)}</small></span><b>↗</b></button>`),...projects.map(p=>`<button data-global-project="${p.id}"><img src="${imageOr(p.cover)}"><span>${escapeHtml(p.title)}<small>Proyecto · ${dateLabel(p.releaseDate)}</small></span><b>↗</b></button>`)].join('')||'<p>No encontramos coincidencias.</p>';results.classList.add('open')});input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();state.catalogSearch=input.value;state.catalogFilter='all';results.classList.remove('open');setView('catalog')}if(e.key==='Escape'){input.value='';results.innerHTML='';results.classList.remove('open')}});results.addEventListener('click',e=>{const song=e.target.closest('[data-global-song]'),project=e.target.closest('[data-global-project]');if(song){results.classList.remove('open');input.blur();songEditor(song.dataset.globalSong)}else if(project){results.classList.remove('open');input.blur();projectEditor(project.dataset.globalProject)}});document.addEventListener('click',e=>{if(!e.target.closest('.global-search'))results.classList.remove('open')})}
boot();
attachGlobalSearch();
bindSimulatorNavigation();
function bindSimulatorNavigation(){document.addEventListener('click',event=>{const spotifyNav=event.target.closest('.nav-item[data-view="spotify"]');if(spotifyNav){state.platform='Spotify';state.simPage='profile';state.simFilter='all'}if(state.view==='spotify'&&event.target.closest('#lyrics-open,#queue-open,#expand-player')){event.preventDefault();event.stopImmediatePropagation();state.simPage=event.target.closest('#lyrics-open')?'lyrics':event.target.closest('#queue-open')?'queue':'player';render();return}const project=event.target.closest('[data-sim-project]');if(project&&$('.sim-shell')){event.preventDefault();event.stopImmediatePropagation();state.selectedProject=project.dataset.simProject;state.simPage='album';render();return}const song=event.target.closest('[data-sim-song]');if(song&&$('.sim-shell')&&!event.target.closest('[data-play]')){event.preventDefault();event.stopImmediatePropagation();state.selectedSong=song.dataset.simSong;if(state.simPage==='profile'){playSong(songById(song.dataset.simSong));return}state.simPage='song';render();return}if(event.target.closest('[data-play-album]')){event.preventDefault();event.stopImmediatePropagation();const album=state.projects.find(item=>item.id===state.selectedProject),track=album?.trackIds?.map(songById).find(Boolean);track?playSong(track):toast('Este álbum aún no tiene canciones');return}if(event.target.closest('[data-player-toggle]')){event.preventDefault();event.stopImmediatePropagation();togglePlay()}},true)}
